arguments.command:
cd /tmp/sv-16650dd30cb74e5ab25afe1fe204a48b/simple-single-project && dotnet list MyApp/MyApp.csproj package --format json 2>/dev/null | python3 -c "import sys,json; data=json.load(sys.stdin); json.dump(data,open('after-cpm-packages.json','w'),indent=2)" && python3 -c "
import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))
bp = {p['id']: p['resolvedVersion'] for f in b['projects'][0]['frameworks'] for p in f['topLevelPackages']}
ap = {p['id']: p['resolvedVersion'] for f in a['projects'][0]['frameworks'] for p in f['topLevelPackages']}
if bp == ap:
    print('All packages resolve to identical versions. Conversion is version-neutral.')
else:
    for k in set(list(bp.keys()) + list(ap.keys())):
        if bp.get(k) != ap.get(k):
            print(f'CHANGED: {k} {bp.get(k)} -> {ap.get(k)}')
"

